// Dedup: bloque (a) les retries Twilio (meme messageSid)
// et (b) les doubles envois utilisateur (meme from+body dans DEDUP_WINDOW_MS).
const data = $input.first().json?.data || {};
const sid = data.messageSid;
const from = data.from || '';
const body = (data.body || '').trim().toLowerCase();

const seen = $getWorkflowStaticData('global');
const now = Date.now();
const DEDUP_WINDOW_MS = 3000;
const TTL_MS = 60000;

if (sid && seen[sid]) return [];
if (sid) seen[sid] = now;

if (from && body) {
  const key = 'dup:' + from + ':' + body;
  const last = seen[key];
  if (last && (now - last) < DEDUP_WINDOW_MS) return [];
  seen[key] = now;
}

const cutoff = now - TTL_MS;
for (const k of Object.keys(seen)) {
  if (typeof seen[k] === 'number' && seen[k] < cutoff) delete seen[k];
}

return [$input.first()];

const phone = $('Wait for Text Response').item.json.data.from;
const summary = $('Summarize Transcript').item.json.output.summary || '';
const prospectName = $('Summarize Transcript').item.json.output.prospect_name || '';
const budget = parseInt($('Summarize Transcript').item.json.output.budget) || 0;
const secteur = $('Summarize Transcript').item.json.output.secteur || '';
const typeBien = $('Summarize Transcript').item.json.output.type_bien || '';

const isVendeur = summary.toLowerCase().includes('vendeur') || summary.toLowerCase().includes('vente');
const typeProjet = isVendeur ? 'vendeur' : 'acheteur';

const blacklist = ['nadia', 'joanel', 'assistante', 'assistant', 'courtier'];
let prenom = '', nom = '';
if (prospectName && !blacklist.includes(prospectName.toLowerCase().split(/\s+/)[0])) {
  const parts = prospectName.trim().split(/\s+/);
  prenom = parts[0] || '';
  nom = parts.slice(1).join(' ') || '';
}

let score = 7;
if (summary.toLowerCase().includes('urgent') || summary.toLowerCase().includes('divorce') || summary.toLowerCase().includes('d\u00e9c\u00e8s')) score = 9;
else if (summary.toLowerCase().includes('pr\u00e9-approuv') || summary.toLowerCase().includes('pre-approv')) score = 8;
else if (summary.toLowerCase().includes('exploration') || summary.toLowerCase().includes('juste regarde')) score = 3;

const isEnglish = summary.toLowerCase().includes('anglophone') || summary.toLowerCase().includes('english');
const langue = isEnglish ? 'en' : 'fr';

const esc = s => s.replace(/'/g, "''");

const query = `
INSERT INTO prospects (
  canal_source, statut, telephone, courtier_id, type_projet,
  score_chaleur, nom, prenom, langue_preferee, resume_ia,
  budget_max, secteur, type_bien, created_at, updated_at
)
VALUES (
  'sms', 'qualifie', '${esc(phone)}',
  (SELECT id FROM courtiers LIMIT 1),
  '${typeProjet}', ${score}, '${esc(nom)}', '${esc(prenom)}', '${langue}',
  '${esc(summary)}',
  ${budget > 0 ? budget : 'NULL'},
  ${secteur ? "'" + esc(secteur) + "'" : 'NULL'},
  ${typeBien ? "'" + esc(typeBien) + "'" : 'NULL'},
  NOW(), NOW()
)
ON CONFLICT (telephone) WHERE telephone IS NOT NULL
DO UPDATE SET
  statut = 'qualifie',
  score_chaleur = ${score},
  type_projet = '${typeProjet}',
  nom = CASE WHEN '${esc(nom)}' != '' THEN '${esc(nom)}' ELSE prospects.nom END,
  prenom = CASE WHEN '${esc(prenom)}' != '' THEN '${esc(prenom)}' ELSE prospects.prenom END,
  langue_preferee = '${langue}',
  resume_ia = '${esc(summary)}',
  budget_max = CASE WHEN ${budget} > 0 THEN ${budget} ELSE prospects.budget_max END,
  secteur = CASE WHEN '${esc(secteur)}' != '' THEN '${esc(secteur)}' ELSE prospects.secteur END,
  type_bien = CASE WHEN '${esc(typeBien)}' != '' THEN '${esc(typeBien)}' ELSE prospects.type_bien END,
  updated_at = NOW()
RETURNING id, telephone, statut, prenom, nom, score_chaleur, budget_max, secteur, type_bien, resume_ia, created_at;
`;

return [{ json: { query, phone, typeProjet, prenom, nom, score, langue, budget, secteur, typeBien, summary: esc(summary) } }];

// Calculate human-like typing delay based on response length
const originalOutput = $json.output || '';
let output = originalOutput;

// Strip any emojis that slipped through
output = output.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F900}-\u{1F9FF}\u{1FA00}-\u{1FA6F}\u{1FA70}-\u{1FAFF}\u{200D}\u{20E3}\u{E0020}-\u{E007F}]/gu, '').trim();

// Strip self-correction lines ("Attends" / "Je retire" only — "Désolé" was too aggressive, it killed legitimate apology messages)
output = output.replace(/\n?Attends[^\n]*\n?/gi, '').replace(/\n?Je retire[^\n]*\n?/gi, '').trim();

// Clean double spaces and double periods
output = output.replace(/\s{2,}/g, ' ').replace(/\.{2,}/g, '.').trim();

// SAFETY: if cleaning emptied the message, fall back to original (without emojis)
if (!output || output.length < 2) {
  output = originalOutput.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{FE00}-\u{FE0F}\u{1F900}-\u{1F9FF}\u{1FA00}-\u{1FA6F}\u{1FA70}-\u{1FAFF}\u{200D}\u{20E3}\u{E0020}-\u{E007F}]/gu, '').trim();
}

// Final safety: never return empty
if (!output) {
  output = 'Salut, peux-tu reformuler ta question?';
}

const charCount = output.length;
const readTime = 3;
const jitter = Math.random() * 5;
let delay = Math.round(readTime + (charCount * 0.15) + jitter);
delay = Math.max(5, Math.min(50, delay));

return [{ json: { _delay: delay, output } }];

const body = (($json && $json.data && $json.data.body) || '').toString().trim().toLowerCase().replace(/[!?.…]+$/, '').trim();
let keyword = 'default';
if (['help', 'aide'].includes(body)) keyword = 'help';
else if (['continuer', 'reprendre', 'start'].includes(body)) keyword = 'continuer';
return { json: { ...$json, keyword } };

// Buffer chaque message dans un tampon par numero, puis stampe l'execution.
// La porte 'Flush If Latest' (apres le Wait) ne laissera passer que la derniere.
const item = $input.first().json;
const data = item?.data || {};
const from = data.from || '';
const body = (data.body || '').trim();

if (!from || !body) return [$input.first()];

const store = $getWorkflowStaticData('global');
store.buffers = store.buffers || {};
const buf = store.buffers[from] || { parts: [] };
buf.parts.push(body);
buf.stamp = Date.now();
store.buffers[from] = buf;

return [{ json: Object.assign({}, item, { _aggStamp: buf.stamp }) }];

// Apres le Wait: si une execution plus recente est arrivee pour ce 'from',
// on abandonne (elle fera le flush). Sinon on concatene le buffer dans data.body.
const item = $input.first().json;
const data = item?.data || {};
const from = data.from || '';
const myStamp = item._aggStamp;

if (!from) return [$input.first()];

const store = $getWorkflowStaticData('global');
const buf = store.buffers && store.buffers[from];

if (!buf || buf.stamp !== myStamp) return [];

const aggregated = buf.parts.join(' ');
delete store.buffers[from];

const out = Object.assign({}, item, { data: Object.assign({}, data, { body: aggregated }) });
return [{ json: out }];
